using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Quantum.Foundation;

internal sealed class ExclusionWidthCompactnessDocument : IScribeDocumentDefinition
{
    private const string Owner = "D5/S3/Quantum/Foundation/ExclusionWidthCompactness.";

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Entire original-effect widths have compact saturation, compact positive layers under faithful labels, and a positive attained global maximum.",
        H("Full-effect widths and compact original-label layers"), Blocks(
        Paragraph(Text("The carrier is any finite dimensional real normed vector space with a closed pointed generating convex cone C and a real-linear unit u strictly positive on every nonzero cone vector. K is the entire normalized base, P contains all its extreme points, and effects are the entire interval from zero to u on C. The ball condition assigns to each actual original pure label an injective affine chart of its entire exclusion by a closed Euclidean unit ball of some positive finite dimension. The dimension may vary and may equal one. Only the global maximum uses a nonzero carrier explicitly.")),
        Paragraph(Text("The original exclusion uses the minimum of every proper effect confirming the label. The existing exclusion predicate instead asks for such an effect vanishing at a specified original state. Compactness of the entire confirming-effect set proves the minimum is attained for every state, including mixed states, and makes the two definitions equal. The existing whole-ball face theorem supplies a single original confirmer vanishing on the entire exclusion. No finite effect menu, selected label set, pure closedness, Pair premise, common metric, spectral representation, fibration or whole-ball continuity is assumed.")),
        Describe.Lean(DescribeId.Create("confirmingeffects"), DeclarationHandle.Create(Owner + "confirmingEffects"),
            H("confirmingEffects"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text("The complete compact slice of all original continuous proper effects evaluating to one at a specified label. In finite dimension every original linear effect has this continuous representation."))), DescribeRole.Definition),
        Describe.Lean(DescribeId.Create("oscillation"), DeclarationHandle.Create(Owner + "oscillation"),
            H("oscillation"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text("The supremum minus infimum of one effect on the whole specified set. Compact nonempty sets attain both extrema."))), DescribeRole.Definition),
        Describe.Lean(DescribeId.Create("width"), DeclarationHandle.Create(Owner + "width"),
            H("width"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text("The supremum of whole-set oscillations over the entire original proper effect interval. On each entire original exclusion ball this supremum is attained by an effect and two endpoints."))), DescribeRole.Definition),
        Describe.Lean(DescribeId.Create("endpointdata"), DeclarationHandle.Create(Owner + "EndpointData"),
            H("EndpointData"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text("One original label, two original states and two full original effects, stored in one finite product. No purity or finite selection of the original domains is part of this type."))), DescribeRole.Definition),
        Describe.Lean(DescribeId.Create("endpointcertificates"), DeclarationHandle.Create(Owner + "endpointCertificates"),
            H("endpointCertificates"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text("Joint data in K cubed times the full effect interval squared. The last effect confirms the label and vanishes at both endpoints; the other effect separates their readings by at least a specified real threshold. Purity is a consequence for positive thresholds with faithful labels, and for threshold one without faithful labels."))), DescribeRole.Definition),
        Describe.Lean(DescribeId.Create("width-upperSemicontinuous"), DeclarationHandle.Create(Owner + "width_upperSemicontinuous"),
            H("Relative upper semicontinuity"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text("On the relative topology of all original pure states, whole-ball width is upper semicontinuous. Only the positive-dimensional entire-ball condition is required; faithful labels and closedness of the pure carrier are not premises. A superlevel is the inverse image of the compact projection of joint endpoint certificates."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("positive-width-layer-compact"), DeclarationHandle.Create(Owner + "positive_width_layer_compact"),
            H("Ambient compact positive layers"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text("For every strictly positive real threshold, all original pure labels whose entire exclusions have width at least that threshold form a compact subset of the original ambient vector space. The empty layer is included. Faithfulness means injectivity of the map from every original pure label to its entire exclusion set. Two distinct common zero endpoints force the compact exposed one-face to have one extreme point; Krein-Milman then makes that entire face a singleton."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("original-exclusion-width"), DeclarationHandle.Create(Owner + "original_exclusion_width"),
            H("Attained positive width on the minimum-defined exclusion"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text("For every original pure label, take every original state at which the infimum over all original confirming effects is zero. Its entire effect width is strictly positive and at most one, and one original effect and two states in this entire set attain it. Compactness of the full confirming interval proves attainment of the infimum at every mixed input, identifying this set with the existing existential exclusion. A separating continuous functional is normalized using its actual extrema on the entire original base and the original unit, producing a proper effect on the whole cone."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("saturated-labels-compact"), DeclarationHandle.Create(Owner + "saturated_labels_compact"),
            H("Compact saturation without faithful labels"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text("The labels of width-one entire exclusions form a compact subset of the original ambient space, possibly empty. Global label injectivity is not assumed. A proper effect reaching one and zero on an entire ball has pure endpoints: its maximum face intersects the ball in a singleton by strict convexity of the entire chart. If that ball had two labels, zero symmetry and the two-common-points rigidity would identify the two endpoint exclusions, forcing a pure point to exclude itself."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("width-tendsto-zero-of-mixed-limit"), DeclarationHandle.Create(Owner + "width_tendsto_zero_of_mixed_limit"),
            H("Width collapse at mixed limits"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text("For every sequence of original pure labels converging in the ambient vector space to a nonpure point, the widths of their entire exclusion balls tend to zero under faithful labels. Each positive layer is ambient compact and therefore excludes a neighborhood of the nonpure limit. No compactness of the entire pure carrier is assumed."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("diameter-tendsto-zero-of-mixed-limit"), DeclarationHandle.Create(Owner + "diameter_tendsto_zero_of_mixed_limit"),
            H("Independent whole-ball diameter collapse"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text("For the same arbitrary convergent sequence and nonpure ambient limit, the diameters of the entire exclusion balls tend to zero under faithful labels. This proof uses compact joint endpoint certificates with a positive endpoint-distance threshold. Such a certificate forces its label to be pure by the common-zero argument. A neighborhood excluding the compact certificate projection bounds every endpoint distance and hence the whole diameter. It uses no comparison between effect width and metric diameter."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("pure-eq-countable-width-layers"), DeclarationHandle.Create(Owner + "pure_eq_countable_width_layers"),
            H("Countable exhaustion of the whole pure carrier"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text("All original pure states are exactly the union of the layers with thresholds one over n plus one, indexed by natural n starting at zero. This is the positive-integer reciprocal exhaustion, with dimension-one ball charts retained. Positivity of each whole-ball width supplies a reciprocal threshold. Under faithful labels the preceding compact-layer theorem makes each member ambient compact."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("width-global-maximum"), DeclarationHandle.Create(Owner + "width_global_maximum"),
            H("Positive global maximum at an original pure label"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text("On a nonzero finite dimensional original space with faithful labels, some actual original pure label attains the supremum of all whole-ball widths. Its width is strictly positive and at most one. Pure spanning supplies a pure label. Its positive width defines a nonempty compact layer, and relative upper semicontinuity gives a maximum on that layer; all labels outside the layer have smaller width. The conclusion gives no equality of the maximum with one."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("near-saturation-subsequence"), DeclarationHandle.Create(Owner + "near_saturation_subsequence"),
            H("Every near-saturated sequence has a saturated limit"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text("Every sequence of original pure labels whose entire-ball widths tend to one admits a strictly increasing map of natural indices and a corresponding ambient-convergent subsequence with a saturated original pure limit. Global injectivity is not used. Each label is paired with an attaining full effect, both endpoints and a common-zero confirmer. A single subsequence in their compact joint product preserves all five objects and reaches a width-one certificate; local saturated-label uniqueness makes its label pure."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("no-saturation-uniform-gap"), DeclarationHandle.Create(Owner + "no_saturation_uniform_gap"),
            H("Uniform upper gap in the absence of saturation"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text("If no original pure label has whole-ball width one, the supremum over all original pure labels is strictly less than one under the positive-dimensional entire-ball condition alone. Maximize endpoint oscillation on the entire compact joint-certificate set. Equality with one would produce a saturated pure label. No uniform gap is assumed, and this result implies neither automatic injectivity nor a saturated ball."))), DescribeRole.Theorem),
        Paragraph(Text("The conclusions are conditional mathematics on the same original full-effect model. They give no automatic injectivity, edge openness, stable-zero-witness principle, saturation propagation, physical realization or quantum representation. A positive attained maximum need not equal one. No literature priority is asserted.")))));
}
